reference_solutions.python:
def solve(weights: list[int], days: int) -> int:
    low, high = max(weights), sum(weights)
    while low < high:
        mid = (low + high) // 2
        if days_needed(weights, mid) <= days:
            high = mid
        else:
            low = mid + 1
    return low


def days_needed(weights, capacity):
    used, load = 1, 0
    for weight in weights:
        if load + weight > capacity:
            used += 1
            load = 0
        load += weight
    return used

